/**
 * @summary Run an immediate sync
 */
export const syncNow = async (
  params?: SyncNowParams,
  options?: RequestInit,
  fetchFn?: typeof globalThis.fetch,
): Promise<syncNowResponse> => {
  const res = await (fetchFn ?? fetch)(getSyncNowUrl(params), {
    ...options,
    method: "POST",
  });

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: syncNowResponse["data"] = body ? JSON.parse(body) : undefined;
  return { data, status: res.status, headers: res.headers } as syncNowResponse;
};

export type getSyncStatusResponse200 = {
  data: SyncStatusOutputBody;
  status: 200;
};

export type getSyncStatusResponseDefault = {
  data: ErrorModel;
  status: Exclude<HTTPStatusCodes, 200>;
};

export type getSyncStatusResponseSuccess = getSyncStatusResponse200 & {
  headers: Headers;
};
export type getSyncStatusResponseError = getSyncStatusResponseDefault & {
  headers: Headers;
};

export type getSyncStatusResponse = getSyncStatusResponseSuccess | getSyncStatusResponseError;

export const getGetSyncStatusUrl = () => {
  return `/api/sync/status`;
};

/**
 * @summary Get sync worker status
 */
export const getSyncStatus = async (
  options?: RequestInit,
  fetchFn?: typeof globalThis.fetch,
): Promise<getSyncStatusResponse> => {
  const res = await (fetchFn ?? fetch)(getGetSyncStatusUrl(), {
    ...options,
    method: "GET",
  });

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: getSyncStatusResponse["data"] = body ? JSON.parse(body) : {};
  return { data, status: res.status, headers: res.headers } as getSyncStatusResponse;
};

export type backfillTokensResponse200 = {
  data: TokenSummary;
  status: 200;
};

export type backfillTokensResponse400 = {
  data: ErrorResponse;
  status: 400;
};

export type backfillTokensResponse500 = {
  data: ErrorResponse;
  status: 500;
};

export type backfillTokensResponseSuccess = backfillTokensResponse200 & {
  headers: Headers;
};
export type backfillTokensResponseError = (backfillTokensResponse400 | backfillTokensResponse500) & {
  headers: Headers;
};

export type backfillTokensResponse = backfillTokensResponseSuccess | backfillTokensResponseError;

export const getBackfillTokensUrl = () => {
  return `/api/tokens/backfill`;
};

/**
 * @summary Backfill token usage from AgentsView payloads
 */
export const backfillTokens = async (
  backfillTokensRequest: NonReadonly<BackfillTokensRequest>,
  options?: RequestInit,
  fetchFn?: typeof globalThis.fetch,
): Promise<backfillTokensResponse> => {
  const getHeaders = (h?: NonNullable<RequestInit["headers"]>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Array.isArray(h)) return Object.fromEntries(h);
    return h;
  };
  const res = await (fetchFn ?? fetch)(getBackfillTokensUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(backfillTokensRequest),
  });

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: backfillTokensResponse["data"] = body ? JSON.parse(body) : {};
  return { data, status: res.status, headers: res.headers } as backfillTokensResponse;
};
